internal final class RMarketJobTest_SubAccountSignals
{
    /// <summary>
    /// Class entry point. The system will call this method when a designated menu 
    /// is selected or when execution starts and this class is set as the startup class.
    /// </summary>
    /// <param name = "_args">The specified arguments.</param>


}

Method.Source:
public static void main(Args _args)
{
    RMarketSubAccount subAccount;
    RMarketTimestamp  tsCursor;
    Dialog            dialog;
    DialogField       dlgSubAccountId;
    DialogField       dlgTsCursor;
    int               calculated;

    dialog = new Dialog("Test subaccount signals");

    dlgSubAccountId = dialog.addFieldValue(extendedTypeStr(RMarketSubAccountId), 'DAT-SA000009');

    dlgTsCursor = dialog.addFieldValue(
        extendedTypeStr(RMarketTimestamp),
        1795107600,
        "Cursor (Unix seconds)");

    if (dialog.run())
    {
        subAccount = RMarketSubAccount::find(dlgSubAccountId.value());

        tsCursor = dlgTsCursor.value();

        calculated = RMarketSignalCalc::calculateSubAccount(subAccount, tsCursor);

        info(strFmt("Subaccount: %1, Strategy: %2", subAccount.SubAccountId, subAccount.StrategyId));

        info(strFmt("Cursor: %1 (%2 UTC)",
            tsCursor,
            RMarketUtil::timestamp2dateTimeUTC(tsCursor)));

        info(strFmt("Signal calculations: %1", calculated));
    }
}
